<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { apiMessage,http } from '@/api/http';import type { DepartmentSummary,ProjectSummary,ReportSummary,UserSummary } from '@/api/types'
const report=ref<ReportSummary>();const projects=ref<ProjectSummary[]>([]);const users=ref<UserSummary[]>([]);const departments=ref<DepartmentSummary[]>([]);const error=ref('');const now=new Date();const filters=reactive({from:`${now.getFullYear()}-01-01`,to:`${now.getFullYear()}-12-31`,projectType:'',projectId:'',departmentId:'',ownerId:'',customerId:''})
async function load(){try{const params=Object.fromEntries(Object.entries(filters).filter(([,v])=>v!==''));report.value=(await http.get('/reports',{params})).data;const [p,u,d]=await Promise.all([http.get('/projects'),http.get('/users'),http.get('/departments')]);projects.value=p.data;users.value=u.data;departments.value=d.data}catch(e){error.value=apiMessage(e)}}onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">MANAGEMENT REPORTS</span><h1>数据报表</h1><p>从项目、部门、成员和客户维度识别进度、负荷、风险与验收效率。</p></div></div><form class="panel report-filters" @submit.prevent="load"><input v-model="filters.from" type="date"><input v-model="filters.to" type="date"><select v-model="filters.projectType"><option value="">全部类型</option><option>INTERNAL</option><option>TEMPORARY</option></select><select v-model="filters.projectId"><option value="">全部项目</option><option v-for="p in projects" :value="p.id">{{ p.name }}</option></select><select v-model="filters.departmentId"><option value="">全部部门</option><option v-for="d in departments" :value="d.id">{{ d.name }}</option></select><select v-model="filters.ownerId"><option value="">全部负责人</option><option v-for="u in users.filter(x=>x.userType==='INTERNAL')" :value="u.id">{{ u.displayName }}</option></select><select v-model="filters.customerId"><option value="">全部客户</option><option v-for="u in users.filter(x=>x.userType==='CUSTOMER')" :value="u.id">{{ u.displayName }}</option></select><button class="primary-button">应用筛选</button></form><p v-if="error" class="error-message">{{ error }}</p>
<div v-if="report" class="report-metrics"><article class="metric-card green"><span>任务完成率</span><strong>{{ report.completionRate }}%</strong><small>{{ report.taskCount }} 项任务</small></article><article class="metric-card coral"><span>任务逾期率</span><strong>{{ report.overdueRate }}%</strong><small>当前未关闭任务</small></article><article class="metric-card sand"><span>里程碑达成率</span><strong>{{ report.milestoneAchievementRate }}%</strong><small>{{ report.projectCount }} 个项目</small></article><article class="metric-card"><span>客户验收效率</span><strong>{{ report.averageAcceptanceHours }}h</strong><small>{{ report.reviewedDeliveries }} 个已验收版本</small></article></div>
<div v-if="report" class="dashboard-grid"><section class="panel"><span class="eyebrow">DEPARTMENT LOAD</span><h2>部门预计工时</h2><p v-for="(value,key) in report.departmentLoad" class="report-line"><span>{{ key }}</span><strong>{{ value }}h</strong></p></section><section class="panel"><span class="eyebrow">RISK DISTRIBUTION</span><h2>风险分布</h2><p v-for="(value,key) in report.riskDistribution" class="report-line"><span>{{ key }}</span><strong>{{ value }}</strong></p></section><section class="panel"><span class="eyebrow">WORKLOGS</span><h2>成员实际工时</h2><p v-for="(value,key) in report.memberHours" class="report-line"><span>{{ key }}</span><strong>{{ value }}h</strong></p></section></div></template>
